package au.monster.tracker;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;

public final class Backup {
    public static final int MAX_BYTES = 64 * 1024 * 1024;
    public record Data(List<Ledger.Event> events,Ledger.Prices prices,List<Receipts.Photo> receipts,Map<String,Object> business) {
        public Data(List<Ledger.Event> events,Ledger.Prices prices){this(events,prices,Ledger.list(),null);}
        public Data(List<Ledger.Event> events,Ledger.Prices prices,List<Receipts.Photo> photos){this(events,prices,photos,null);}
        public Data(List<Ledger.Event> events,Ledger.Prices prices,Map<String,Object> business){this(events,prices,Ledger.list(),business);}
    }
    public static Map<String,Object> eventMap(Ledger.Event e){Map<String,Object> m=new LinkedHashMap<>();m.put("id",e.id());m.put("timestamp",Ledger.iso(e.timestamp()));m.put("recordedAt",Ledger.iso(e.recordedAt()));m.put("type",e.type());m.put("quantity",e.quantity());m.put("payment",e.payment());m.put("revenue",e.revenue());m.put("fee",e.fee());m.put("cost",e.cost());m.put("note",e.note());m.put("target",e.target());return m;}
    public static Ledger.Event event(Object value){Map<String,Object> m=object(value);keys(m,Ledger.set("id","timestamp","recordedAt","type","quantity","payment","revenue","fee","cost","note","target"));return new Ledger.Event(string(m,"id"),time(m.get("timestamp"),true),time(m.get("recordedAt"),false),string(m,"type"),number(m,"quantity"),string(m,"payment"),number(m,"revenue"),number(m,"fee"),number(m,"cost"),string(m,"note"),m.get("target")==null?null:string(m,"target"));}
    public static String encode(Data data){Ledger.validateAll(data.events);Receipts.validate(data.receipts,data.events);Map<String,Object> payload=new LinkedHashMap<>();payload.put("format","monster-tracker-offline");payload.put("version",data.business==null?2L:(data.business.containsKey("catalog")?4L:3L));payload.put("currency","AUD");payload.put("timeZone","Australia/Perth");payload.put("exportedAt",Instant.now().toString());payload.put("prices",priceMap(data.prices));List<Object> events=new ArrayList<>();for(var e:data.events)events.add(eventMap(e));payload.put("events",events);List<Object> photos=new ArrayList<>();for(var photo:data.receipts)photos.add(Receipts.map(photo));payload.put("receipts",photos);if(data.business!=null){BusinessBackup.validate(data.business,data.events);payload.put("business",data.business);}String checksum=hash(Json.write(payload));payload.put("sha256",checksum);String encoded=Json.write(payload);if(encoded.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)fail("Backup exceeds 64 MB; nothing was exported.");return encoded;}
    public static Data decode(String text){Map<String,Object> root=object(Json.parse(text));long version=number(root,"version");Set<String> fields=new HashSet<>(Ledger.set("format","version","currency","timeZone","exportedAt","prices","events","sha256"));if(version>=2)fields.add("receipts");if(version>=3)fields.add("business");keys(root,fields);if(!string(root,"format").equals("monster-tracker-offline")||(version!=1&&version!=2&&version!=3&&version!=4)||!string(root,"currency").equals("AUD")||!string(root,"timeZone").equals("Australia/Perth"))fail("Unsupported backup format, currency or time zone.");time(root.get("exportedAt"),false);String expected=string(root,"sha256");Map<String,Object> unsigned=new LinkedHashMap<>(root);unsigned.remove("sha256");if(!MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),hash(Json.write(unsigned)).getBytes(StandardCharsets.UTF_8)))fail("Backup checksum failed. File may be incomplete or changed.");Map<String,Object> p=object(root.get("prices"));keys(p,Ledger.set("single","deal"));Ledger.Prices prices=new Ledger.Prices(number(p,"single"),number(p,"deal"));if(!(root.get("events") instanceof List<?>))fail("Transactions must be an array.");List<Ledger.Event> events=new ArrayList<>();for(Object e:(List<?>)root.get("events"))events.add(event(e));Ledger.validateAll(events);List<Receipts.Photo> photos=new ArrayList<>();if(version>=2){if(!(root.get("receipts") instanceof List<?>))fail("Receipts must be an array.");for(Object photo:(List<?>)root.get("receipts"))photos.add(Receipts.parse(photo));}Receipts.validate(photos,events);Map<String,Object> business=version>=3?object(root.get("business")):null;if(business!=null)BusinessBackup.validate(business,events);return new Data(Ledger.copy(events),prices,Ledger.copy(photos),business);}
    public static String csv(List<Ledger.Event> events){StringBuilder b=new StringBuilder("\uFEFFid,event_timestamp_utc,perth_time,recorded_at_utc,type,quantity,payment,revenue_aud,fee_aud,purchase_cost_aud,stored_sale_price_aud,note,corrects_id,corrected\r\n");Set<String> corrected=new HashSet<>();for(var e:events)if(e.type().equals("undo"))corrected.add(e.target());for(var e:events){String[] fields={e.id(),Ledger.iso(e.timestamp()),e.timestamp()==null?"":Ledger.displayTime(e.timestamp()),Ledger.iso(e.recordedAt()),e.type(),Long.toString(e.quantity()),e.payment(),Ledger.inputMoney(e.revenue()),Ledger.inputMoney(e.fee()),Ledger.inputMoney(e.cost()),(e.type().equals("single")||e.type().equals("deal"))?Ledger.inputMoney(e.revenue()):"",e.note(),e.target(),Boolean.toString(corrected.contains(e.id()))};for(int i=0;i<fields.length;i++){if(i>0)b.append(',');String v=fields[i]==null?"":fields[i];if(i==11&&(v.startsWith("=")||v.startsWith("+")||v.startsWith("-")||v.startsWith("@")))v="'"+v;b.append('"').append(v.replace("\"","\"\"")).append('"');}b.append("\r\n");}return b.toString();}
    @SuppressWarnings("unchecked") private static Map<String,Object> object(Object v){if(!(v instanceof Map<?,?>))fail("Expected a JSON object.");return (Map<String,Object>)v;}
    private static void keys(Map<String,Object> m,Set<String> expected){if(!m.keySet().equals(expected))fail("Backup fields are missing or unknown.");}
    private static String string(Map<String,Object> m,String key){Object v=m.get(key);if(!(v instanceof String))fail("Invalid text field: "+key);return (String)v;}
    private static long number(Map<String,Object> m,String key){Object v=m.get(key);if(!(v instanceof Long))fail("Invalid integer field: "+key);return (Long)v;}
    private static Long time(Object v,boolean nullable){if(v==null&&nullable)return null;if(!(v instanceof String))fail("Invalid timestamp.");try{return Instant.parse((String)v).toEpochMilli();}catch(RuntimeException ex){throw new IllegalArgumentException("Invalid timestamp.");}}
    private static String hash(String value){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:bytes)b.append(String.format("%02x",x&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
    private static Map<String,Object> priceMap(Ledger.Prices p){Map<String,Object> m=new LinkedHashMap<>();m.put("single",p.single());m.put("deal",p.deal());return m;}
    private static void fail(String s){throw new IllegalArgumentException(s);}
    private Backup(){}
}
